select od.food_name name, sum(od.quantity) number
from order_detail od,
     orders o
where od.order_id = o.id
  and o.store_id = #{storeId}
  and o.status = #{status}
  and o.updated_at between #{begin} and #{end}
group by name
order by number desc limit 0,10

